 byte[]terrain=new byte[16384];for(int y=0;y<128;y++)for(int x=0;x<128;x++)terrain[y*128+x]=(byte)(s/37%3==1&&x==33||s/37%3==2&&y==33?19:0);e.writeMemory(toAddr(0x58aaaa),terrain);put(e,0x635b78+68,1,2);put(e,0x635c78+68*32,1,0);put(e,0x635c78+68*32+1,1,1);put(e,0x632194,4,R+144);put(e,0x622dc4,1,s/41%2);put(e,0x586973,1,0);
